{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已完成任务按项目工时汇总Top2",
      "business_question": "只看已完成任务，按项目汇总工时总和，降序取前两名？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：获取已完成任务中工时投入最高的两个项目。删除此任务将无法支持资源分配或优先级决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "top_n",
          "params": {
            "field": "total_hours",
            "direction": "desc",
            "n": 2
          }
        }
      ]
    }
  ]
}
